package com.primehr.rewardsrecognition.report;
import com.primehr.security.PrimeHrAction;import com.primehr.security.RrAwardPermissionGuard;import com.primehr.security.AgencyScopeResolver;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/primehr/v1/rewards-recognition/reports")
public class RrReportController{private final RrReportService service;private final RrAwardPermissionGuard permissions;private final AgencyScopeResolver agencies;public RrReportController(RrReportService s,RrAwardPermissionGuard p,AgencyScopeResolver a){service=s;permissions=p;agencies=a;}
 @GetMapping(value="/nominations/{id}.pdf",produces=MediaType.APPLICATION_PDF_VALUE)public ResponseEntity<byte[]>nomination(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){var s=permissions.require(RrAwardPermissionGuard.REPORT,PrimeHrAction.ACCESS,t);return pdf("praise-nomination-"+id,service.nomination(agencies.resolveAgencyId(a),id,a.getName(),s));}
 @GetMapping(value="/evaluation-cases/{id}.pdf",produces=MediaType.APPLICATION_PDF_VALUE)public ResponseEntity<byte[]>evaluation(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){var s=permissions.require(RrAwardPermissionGuard.REPORT,PrimeHrAction.ACCESS,t);return pdf("praise-evaluation-"+id,service.evaluation(agencies.resolveAgencyId(a),id,a.getName(),s));}
 @GetMapping(value="/awards/{id}.pdf",produces=MediaType.APPLICATION_PDF_VALUE)public ResponseEntity<byte[]>award(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){var s=permissions.require(RrAwardPermissionGuard.REPORT,PrimeHrAction.ACCESS,t);return pdf("praise-award-"+id,service.award(agencies.resolveAgencyId(a),id,a.getName(),s));}
 @GetMapping(value="/annual-register.pdf",produces=MediaType.APPLICATION_PDF_VALUE)public ResponseEntity<byte[]>annual(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestParam int year){permissions.requireAgency(RrAwardPermissionGuard.REPORT,PrimeHrAction.ACCESS,t);return pdf("annual-praise-register-"+year,service.annualRegister(agencies.resolveAgencyId(a),year,a.getName()));}
 @GetMapping("/analytics")public RrReportData.Analytics analytics(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestParam int year){permissions.requireAgency(RrAwardPermissionGuard.ANALYTICS,PrimeHrAction.ACCESS,t);return service.analytics(agencies.resolveAgencyId(a),year);}
 private static ResponseEntity<byte[]>pdf(String name,byte[]content){return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.inline().filename(name+".pdf").build().toString()).header(HttpHeaders.CACHE_CONTROL,"no-store").body(content);}}
